         4)*cs61 + at3(2, 2, 2, 4)*cs0*inv_Z*ps0(4)*s_2*w2(2, 2) - at3(2, 2, 3, 4)*cs18 - at2(2, &
         3, 4)*cs62 + at3(2, 3, 3, 4)*cs0*inv_Z*ps0(4)*s_2*w2(3, 3) + cs131*(-at1(2, 1)*cs23 + &
         (1.0_wp/2.0_wp)*at1(2, 2)*ps0(1)*s_3 - at1(2, 3)*cs9 - at1(2, 4)*cs14)
      vjp_f1_rA(3) = &
         (1.0_wp/6.0_wp)*at3(1, 1, 3, 1)*cs0*cs10*inv_Z*s_3*w2(1, 1) - at3(1, 2, 3, 1)*cs25 - &
         at2(1, 3, 1)*cs90 - at3(1, 3, 3, 1)*cs26 + (1.0_wp/6.0_wp)*at3(2, 2, 3, &
         1)*cs0*cs10*inv_Z*s_3*w2(2, 2) - at2(2, 3, 1)*cs88 - at3(2, 3, 3, 1)*cs27 - at1(3, &
         1)*cs120 - at2(3, 3, 1)*cs85 + (1.0_wp/6.0_wp)*at3(3, 3, 3, 1)*cs0*cs10*inv_Z*s_3*w2(3, &
         3) - at3(1, 1, 3, 2)*cs5 - at3(1, 2, 3, 2)*cs11 - at2(1, 3, 2)*cs65 - at3(1, 3, 3, &
         2)*cs12 - at3(2, 2, 3, 2)*cs6 - at2(2, 3, 2)*cs67 - at3(2, 3, 3, 2)*cs13 - at1(3, &
         2)*cs111 - at2(3, 3, 2)*cs68 - at3(3, 3, 3, 2)*cs7 + at3(1, 1, 3, 3)*cs0*cs9*inv_Z*w2(1, &
         1) - at3(1, 2, 3, 3)*cs20 - at2(1, 3, 3)*cs44 - at3(1, 3, 3, 3)*cs21 + at3(2, 2, 3, &
         3)*cs0*cs9*inv_Z*w2(2, 2) - at2(2, 3, 3)*cs47 - at3(2, 3, 3, 3)*cs22 - at2(3, 3, 3)*cs49 &
         + at3(3, 3, 3, 3)*cs0*cs9*inv_Z*w2(3, 3) + at3(1, 1, 3, 4)*cs0*inv_Z*ps0(4)*s_2*w2(1, 1) &
         - at3(1, 2, 3, 4)*cs16 - at2(1, 3, 4)*cs59 - at3(1, 3, 3, 4)*cs17 + at3(2, 2, 3, &
         4)*cs0*inv_Z*ps0(4)*s_2*w2(2, 2) - at2(2, 3, 4)*cs61 - at3(2, 3, 3, 4)*cs18 - at1(3, &
         4)*cs99 - at2(3, 3, 4)*cs62 + at3(3, 3, 3, 4)*cs0*inv_Z*ps0(4)*s_2*w2(3, 3) + &
         cs131*(-at1(3, 1)*cs23 + (1.0_wp/2.0_wp)*at1(3, 2)*ps0(1)*s_3 - at1(3, 3)*cs9 - at1(3, &
         4)*cs14)

   end subroutine svdw_vjp_eval

   pure module subroutine svdw_radius_vjp_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, atd0, atd1, atd2, &
                                        w0, w1, w2, vjp_f1_rad)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Accumulated power-sum tensor d^0 p_kind / dr^0, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(nkind)
      !> Accumulated power-sum tensor d^1 p_kind / dr^1, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(3, nkind)
      !> Accumulated power-sum tensor d^2 p_kind / dr^2, summed over all active atoms; last index
      !> selects the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(3, 3, nkind)
      !> Atom-A radius tensor d/dR_a of the order-0 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd0(nkind)
      !> Atom-A radius tensor d/dR_a of the order-1 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd1(3, nkind)
      !> Atom-A radius tensor d/dR_a of the order-2 kind tensor from svdw_atom_rad_eval; last index
      !> selects the kind
      real(wp), intent(in) :: atd2(3, 3, nkind)
      !> Adjoint weight of the level-set value S
      real(wp), intent(in) :: w0
      !> Adjoint weights of the spatial gradient dS/dr
      real(wp), intent(in) :: w1(3)
      !> Adjoint weights of the spatial Hessian d^2S/dr^2; a general 3x3, contracted over all nine
      !> entries
      real(wp), intent(in) :: w2(3, 3)
      !> w0 f1_rad + w1 . f2_r_rad + w2 : f3_rr_rad of this atom; a scalar, since a radius carries
      !> no derivative index
      real(wp), intent(out) :: vjp_f1_rad

      !> Assembled blending polynomial Z and its reciprocal
      real(wp) :: Z, inv_Z
      !> Common subexpressions of the contracted jet
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28
      real(wp) :: cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs41, cs42
      real(wp) :: cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52, cs53, cs54, cs55, cs56
      real(wp) :: cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70
      real(wp) :: cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84
      real(wp) :: cs85, cs86, cs87, cs88, cs89, cs90, cs91, cs92, cs93, cs94, cs95, cs96, cs97, cs98
      real(wp) :: cs99, cs100, cs101

      Z = &
         (1.0_wp/6.0_wp)*(ps0(1)*ps0(1)*ps0(1))*s_3 - 1.0_wp/2.0_wp*ps0(1)*ps0(2)*s_3 + ps0(3)*s_1 &
         - 1.0_wp/2.0_wp*ps0(3)*s_2 + (1.0_wp/3.0_wp)*ps0(3)*s_3 + &
         (1.0_wp/2.0_wp)*(ps0(4)*ps0(4))*s_2
      inv_Z = 1.0_wp/Z
      cs0 = 1.0_wp/blend_k
      cs1 = cs0*inv_Z
      cs2 = ps0(1)*s_3
      cs3 = (1.0_wp/2.0_wp)*cs2
      cs4 = cs1*cs3
      cs5 = ps0(4)*s_2
      cs6 = cs1*cs5
      cs7 = (1.0_wp/3.0_wp)*s_3
      cs8 = cs7 + s_1 - 1.0_wp/2.0_wp*s_2
      cs9 = cs1*cs8
      cs10 = 3.0_wp*(ps0(1)*ps0(1)) - 3.0_wp*ps0(2)
      cs11 = (1.0_wp/6.0_wp)*cs10
      cs12 = cs1*s_3
      cs13 = cs11*cs12
      cs14 = ps1(2, 2)*s_3
      cs15 = (1.0_wp/2.0_wp)*cs14
      cs16 = cs11*s_3
      cs17 = -cs15*ps0(1) + cs16*ps1(2, 1) + cs5*ps1(2, 4) + cs8*ps1(2, 3)
      cs18 = cs0*(inv_Z*inv_Z)
      cs19 = cs17*cs18
