      cs24 = cs18*cs23
      cs25 = cs24*cs8
      cs26 = 2.0_wp*s_1 - s_2 + (2.0_wp/3.0_wp)*s_3
      cs27 = ps1(1, 2)*s_3
      cs28 = (1.0_wp/2.0_wp)*cs27
