      cs31 = cs18*cs30
      cs32 = cs31*cs8
      cs33 = cs1*s_2
      cs34 = cs33*ps1(2, 4)
      cs35 = cs19*cs5
      cs36 = -cs34 + cs35
      cs37 = cs33*ps1(3, 4)
      cs38 = cs24*cs5
      cs39 = -cs37 + cs38
      cs40 = cs33*ps1(1, 4)
      cs41 = cs31*cs5
      cs42 = -cs40 + cs41
      cs43 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(2, 1)*s_3 - cs19*cs3
      cs44 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(3, 1)*s_3 - cs24*cs3
      cs45 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps1(1, 1)*s_3 - cs3*cs31
      cs46 = cs2*ps1(1, 1)
      cs47 = -cs28 + cs46
      cs48 = cs1*cs47
      cs49 = -cs48
      cs50 = cs16*cs31 + cs49
      cs51 = cs2*ps1(2, 1)
      cs52 = -cs15 + cs51
      cs53 = cs1*cs52
      cs54 = -cs53
      cs55 = cs16*cs19
      cs56 = cs54 + cs55
      cs57 = cs2*ps1(3, 1)
      cs58 = -cs22 + cs57
      cs59 = cs1*cs58
      cs60 = cs10*cs7
      cs61 = cs1*cs22 - cs1*cs57
      cs62 = cs16*cs24 + cs61
      cs63 = cs1*cs15 - cs1*cs51
      cs64 = cs55 + cs63
      cs65 = ps1(1, 4)*s_2
      cs66 = ps1(2, 4)*s_2
      cs67 = ps1(3, 4)*s_2
      cs68 = cs31*s_2
      cs69 = cs19*cs65 - cs33*ps2(1, 2, 4) + cs68*ps1(2, 4)
      cs70 = cs24*cs65 - cs33*ps2(1, 3, 4) + cs68*ps1(3, 4)
      cs71 = cs19*cs67 + cs24*cs66 - cs33*ps2(2, 3, 4)
      cs72 = cs1*cs29
      cs73 = cs12*ps1(2, 1)
      cs74 = ps1(2, 1)*s_3
      cs75 = ps1(3, 1)*s_3
      cs76 = (1.0_wp/2.0_wp)*cs29
      cs77 = (1.0_wp/2.0_wp)*cs31
      cs78 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps2(1, 2, 1)*s_3 - cs19*cs76 - cs74*cs77
      cs79 = (1.0_wp/2.0_wp)*cs0*inv_Z*ps2(1, 3, 1)*s_3 - cs24*cs76 - cs75*cs77
      cs80 = &
         (1.0_wp/2.0_wp)*cs0*inv_Z*ps2(2, 3, 1)*s_3 - 1.0_wp/2.0_wp*cs19*cs75 - &
         1.0_wp/2.0_wp*cs24*cs74
      cs81 = (1.0_wp/2.0_wp)*cs12
      cs82 = cs1*cs2
      cs83 = cs18*cs47
      cs84 = cs17*cs83 + cs31*cs52 - cs72*ps1(2, 1) + cs81*ps2(1, 2, 2) - cs82*ps2(1, 2, 1)
      cs85 = cs23*cs83 + cs31*cs58 - cs72*ps1(3, 1) + cs81*ps2(1, 3, 2) - cs82*ps2(1, 3, 1)
      cs86 = cs19*cs58 + cs24*cs52 - cs73*ps1(3, 1) + cs81*ps2(2, 3, 2) - cs82*ps2(2, 3, 1)
      cs87 = cs18*cs5
      cs88 = cs18*s_2
      cs89 = cs18*cs3
      cs90 = cs18*ps1(1, 1)
      cs91 = cs18*cs8
      cs92 = cs16*cs18
      cs93 = 2.0_wp*cs0*(inv_Z*inv_Z*inv_Z)
      cs94 = cs18*ps1(2, 1)
      cs95 = cs18*cs52
      cs96 = cs18*ps1(3, 1)
      cs97 = cs88*ps1(1, 4)
      cs98 = cs30*cs93
      cs99 = &
         -cs15*cs90 - cs17*cs98 + cs83*ps1(2, 1) + cs87*ps2(1, 2, 4) - cs89*ps2(1, 2, 2) + &
         cs91*ps2(1, 2, 3) + cs92*ps2(1, 2, 1) + cs97*ps1(2, 4)
      cs100 = &
         -cs22*cs90 - cs23*cs98 + cs83*ps1(3, 1) + cs87*ps2(1, 3, 4) - cs89*ps2(1, 3, 2) + &
         cs91*ps2(1, 3, 3) + cs92*ps2(1, 3, 1) + cs97*ps1(3, 4)
      cs101 = &
         -cs17*cs23*cs93 - cs22*cs94 + cs87*ps2(2, 3, 4) + cs88*ps1(2, 4)*ps1(3, 4) - cs89*ps2(2, &
         3, 2) + cs91*ps2(2, 3, 3) + cs92*ps2(2, 3, 1) + cs95*ps1(3, 1)
      vjp_f1_rad = &
         atd0(1)*(-cs48*w1(1) - cs53*w1(2) - cs59*w1(3) + cs84*w2(1, 2) + cs84*w2(2, 1) + &
         cs85*w2(1, 3) + cs85*w2(3, 1) + cs86*w2(2, 3) + cs86*w2(3, 2) + w2(1, 1)*(-cs12*(ps1(1, &
         1)*ps1(1, 1)) + cs31*(-cs27 + 2.0_wp*cs46) + cs81*ps2(1, 1, 2) - cs82*ps2(1, 1, 1)) + &
         w2(2, 2)*(-cs12*(ps1(2, 1)*ps1(2, 1)) + cs19*(-cs14 + 2.0_wp*cs51) + cs81*ps2(2, 2, 2) - &
         cs82*ps2(2, 2, 1)) + w2(3, 3)*(-cs12*(ps1(3, 1)*ps1(3, 1)) + cs24*(-cs21 + 2.0_wp*cs57) + &
         cs81*ps2(3, 3, 2) - cs82*ps2(3, 3, 1))) + atd1(1, 1)*(-cs13*w1(1) + cs62*w2(1, 3) + &
         cs62*w2(3, 1) + cs64*w2(1, 2) + cs64*w2(2, 1) + w2(1, 1)*(cs1*cs28 - cs1*cs46 + cs31*cs60 &
         + cs49)) - atd2(1, 1, 1)*cs13*w2(1, 1) + atd2(1, 2, 1)*(-cs13*w2(1, 2) - cs13*w2(2, 1)) + &
         atd2(1, 3, 1)*(-cs13*w2(1, 3) - cs13*w2(3, 1)) + atd1(2, 1)*(-cs13*w1(2) + cs50*w2(1, 2) &
         + cs50*w2(2, 1) + cs62*w2(2, 3) + cs62*w2(3, 2) + w2(2, 2)*(cs19*cs60 + cs54 + cs63)) - &
         atd2(2, 2, 1)*cs13*w2(2, 2) + atd2(2, 3, 1)*(-cs13*w2(2, 3) - cs13*w2(3, 2)) + atd1(3, &
         1)*(-cs13*w1(3) + cs50*w2(1, 3) + cs50*w2(3, 1) + cs56*w2(2, 3) + cs56*w2(3, 2) + w2(3, &
         3)*(cs24*cs60 - cs59 + cs61)) - atd2(3, 3, 1)*cs13*w2(3, 3) + &
         atd0(2)*((1.0_wp/2.0_wp)*cs12*ps1(3, 1)*w1(3) + (1.0_wp/2.0_wp)*cs72*w1(1) + &
         (1.0_wp/2.0_wp)*cs73*w1(2) + cs78*w2(1, 2) + cs78*w2(2, 1) + cs79*w2(1, 3) + cs79*w2(3, &
         1) + cs80*w2(2, 3) + cs80*w2(3, 2) + w2(1, 1)*((1.0_wp/2.0_wp)*cs0*inv_Z*ps2(1, 1, 1)*s_3 &
         - cs29*cs31) + w2(2, 2)*((1.0_wp/2.0_wp)*cs0*inv_Z*ps2(2, 2, 1)*s_3 - cs19*cs74) + w2(3, &
         3)*((1.0_wp/2.0_wp)*cs0*inv_Z*ps2(3, 3, 1)*s_3 - cs24*cs75)) + atd1(1, 2)*(cs4*w1(1) + &
         cs43*w2(1, 2) + cs43*w2(2, 1) + cs44*w2(1, 3) + cs44*w2(3, 1) + w2(1, &
         1)*(cs0*inv_Z*ps1(1, 1)*s_3 - cs2*cs31)) + atd2(1, 1, 2)*cs4*w2(1, 1) + atd2(1, 2, &
         2)*(cs4*w2(1, 2) + cs4*w2(2, 1)) + atd2(1, 3, 2)*(cs4*w2(1, 3) + cs4*w2(3, 1)) + atd1(2, &
         2)*(cs4*w1(2) + cs44*w2(2, 3) + cs44*w2(3, 2) + cs45*w2(1, 2) + cs45*w2(2, 1) + w2(2, &
         2)*(cs0*inv_Z*ps1(2, 1)*s_3 - cs19*cs2)) + atd2(2, 2, 2)*cs4*w2(2, 2) + atd2(2, 3, &
         2)*(cs4*w2(2, 3) + cs4*w2(3, 2)) + atd1(3, 2)*(cs4*w1(3) + cs43*w2(2, 3) + cs43*w2(3, 2) &
         + cs45*w2(1, 3) + cs45*w2(3, 1) + w2(3, 3)*(cs0*inv_Z*ps1(3, 1)*s_3 - cs2*cs24)) + &
         atd2(3, 3, 2)*cs4*w2(3, 3) + atd1(1, 3)*(cs20*w2(1, 2) + cs20*w2(2, 1) + cs25*w2(1, 3) + &
         cs25*w2(3, 1) + cs26*cs31*w2(1, 1) - cs9*w1(1)) - atd2(1, 1, 3)*cs9*w2(1, 1) + atd2(1, 2, &
         3)*(-cs9*w2(1, 2) - cs9*w2(2, 1)) + atd2(1, 3, 3)*(-cs9*w2(1, 3) - cs9*w2(3, 1)) + &
         atd1(2, 3)*(cs19*cs26*w2(2, 2) + cs25*w2(2, 3) + cs25*w2(3, 2) + cs32*w2(1, 2) + &
         cs32*w2(2, 1) - cs9*w1(2)) - atd2(2, 2, 3)*cs9*w2(2, 2) + atd2(2, 3, 3)*(-cs9*w2(2, 3) - &
         cs9*w2(3, 2)) + atd1(3, 3)*(cs20*w2(2, 3) + cs20*w2(3, 2) + cs24*cs26*w2(3, 3) + &
         cs32*w2(1, 3) + cs32*w2(3, 1) - cs9*w1(3)) - atd2(3, 3, 3)*cs9*w2(3, 3) + &
         atd0(4)*(-cs34*w1(2) - cs37*w1(3) - cs40*w1(1) + cs69*w2(1, 2) + cs69*w2(2, 1) + &
         cs70*w2(1, 3) + cs70*w2(3, 1) + cs71*w2(2, 3) + cs71*w2(3, 2) + w2(1, &
         1)*(2.0_wp*cs31*cs65 - cs33*ps2(1, 1, 4)) + w2(2, 2)*(2.0_wp*cs19*cs66 - cs33*ps2(2, 2, &
         4)) + w2(3, 3)*(2.0_wp*cs24*cs67 - cs33*ps2(3, 3, 4))) + atd1(1, 4)*(cs36*w2(1, 2) + &
         cs36*w2(2, 1) + cs39*w2(1, 3) + cs39*w2(3, 1) - cs6*w1(1) + w2(1, 1)*(-2.0_wp*cs40 + &
         2.0_wp*cs41)) - atd2(1, 1, 4)*cs6*w2(1, 1) + atd2(1, 2, 4)*(-cs6*w2(1, 2) - cs6*w2(2, 1)) &
         + atd2(1, 3, 4)*(-cs6*w2(1, 3) - cs6*w2(3, 1)) + atd1(2, 4)*(cs39*w2(2, 3) + cs39*w2(3, &
         2) + cs42*w2(1, 2) + cs42*w2(2, 1) - cs6*w1(2) + w2(2, 2)*(-2.0_wp*cs34 + 2.0_wp*cs35)) - &
         atd2(2, 2, 4)*cs6*w2(2, 2) + atd2(2, 3, 4)*(-cs6*w2(2, 3) - cs6*w2(3, 2)) + atd1(3, &
         4)*(cs36*w2(2, 3) + cs36*w2(3, 2) + cs42*w2(1, 3) + cs42*w2(3, 1) - cs6*w1(3) + w2(3, &
         3)*(-2.0_wp*cs37 + 2.0_wp*cs38)) - atd2(3, 3, 4)*cs6*w2(3, 3) + (atd0(1)*cs16 - &
         atd0(2)*cs3 + atd0(3)*cs8 + atd0(4)*cs5)*(-cs1*w0 + cs100*w2(1, 3) + cs100*w2(3, 1) + &
         cs101*w2(2, 3) + cs101*w2(3, 2) + cs19*w1(2) + cs24*w1(3) + cs31*w1(1) + cs99*w2(1, 2) + &
         cs99*w2(2, 1) + w2(1, 1)*(-cs28*cs90 - (cs30*cs30)*cs93 + cs83*ps1(1, 1) + cs87*ps2(1, 1, &
         4) + cs88*(ps1(1, 4)*ps1(1, 4)) - cs89*ps2(1, 1, 2) + cs91*ps2(1, 1, 3) + cs92*ps2(1, 1, &
         1)) + w2(2, 2)*(-cs15*cs94 - (cs17*cs17)*cs93 + cs87*ps2(2, 2, 4) + cs88*(ps1(2, &
         4)*ps1(2, 4)) - cs89*ps2(2, 2, 2) + cs91*ps2(2, 2, 3) + cs92*ps2(2, 2, 1) + cs95*ps1(2, &
         1)) + w2(3, 3)*(-cs22*cs96 - (cs23*cs23)*cs93 + cs58*cs96 + cs87*ps2(3, 3, 4) + &
         cs88*(ps1(3, 4)*ps1(3, 4)) - cs89*ps2(3, 3, 2) + cs91*ps2(3, 3, 3) + cs92*ps2(3, 3, 1)))

   end subroutine svdw_radius_vjp_eval

   pure module subroutine svdw_hvp_vjp_eval(blend_k, s_1, s_2, s_3, ps0, ps1, ps2, at0, at1, at2, at3, &
                                     w0, w1, w2, hvp_vjp_ws0, hvp_vjp_ws1, hvp_vjp_ws2)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
